(2888924, 404403, 61958, '<td valign="top">Picture could use some additional editing ie. the brightness of the hand from the flash. also cropping the image more to focus on the subject eliminating background distractions like the microwave.</td>', 'Picture could use some additional editing ie. the brightness of the hand from the flash. also cropping the image more to focus on the subject eliminating background distractions like the microwave.', '2006-10-02 21:35:24.000000', NULL, 1),
(2889044, 404659, 63966, '<td valign="top">Toasted Compact flash for more saturated colors. <br/>Good concept.  The chrome would look better w/o smudges</td>', 'Toasted Compact flash for more saturated colors. Good concept.  The chrome would look better w/o smudges', '2006-10-02 22:02:10.000000', NULL, 1),
