(2897079, 404673, 65234, '<td valign="top">I like the pic and the idea a lot, but I think there are too many things present.  Wish I could rate it higher.</td>', 'I like the pic and the idea a lot, but I think there are too many things present.  Wish I could rate it higher.', '2006-10-04 19:41:38.000000', NULL, 1),
(2897086, 404707, 65234, '<td valign="top">Awfully funny, in all senses of that adjective!!  Nice composition and DOF.</td>', 'Awfully funny, in all senses of that adjective!!  Nice composition and DOF.', '2006-10-04 19:44:34.000000', NULL, 1),
(2897091, 403179, 65234, '<td valign="top">I''m not sure they make sense, but the objects make at least as much sense as the title ;-)  Nicely shot.</td>', 'I''m not sure they make sense, but the objects make at least as much sense as the title ;-)  Nicely shot.', '2006-10-04 19:45:53.000000', NULL, 1),
(2897176, 404669, 23484, '<td valign="top">Neat idea.  I really like the dismal look to it.</td>', 'Neat idea.  I really like the dismal look to it.', '2006-10-04 20:15:47.000000', NULL, 1),
(2897205, 404594, 59415, '<td valign="top">Guns N Roses is what I would have titled this.</td>', 'Guns N Roses is what I would have titled this.', '2006-10-04 20:24:47.000000', NULL, 1),
