(2901796, 403336, 34013, '<td valign="top">great concept!!</td>', 'great concept!!', '2006-10-06 01:12:39.000000', NULL, 1),
(2901798, 403463, 19831, '<td valign="top">OMG, this shot just totally cracks me up! I mean, I am literally laughing out loud here. Not just the title, and the actual concept, but it''s execution is perfect parody of the whole dramatic idea,  that you see in movies, tv, ads, etc. The moody lighting, off centered comp to the left, the lost, forlorn, remorseful gaze off the frame of the subject. Just awesome. Awesome, awesome, awesome. It takes a lot for a shot with a figure, toy, etc. to move me at all, but man, you''ve totally nailed this one. Nice freakin'' job :-)</td>', 'OMG, this shot just totally cracks me up! I mean, I am literally laughing out loud here. Not just the title, and the actual concept, but it''s execution is perfect parody of the whole dramatic idea,  that you see in movies, tv, ads, etc. The moody lighting, off centered comp to the left, the lost, forlorn, remorseful gaze off the frame of the subject. Just awesome. Awesome, awesome, awesome. It takes a lot for a shot with a figure, toy, etc. to move me at all, but man, you''ve totally nailed this one. Nice freakin'' job :-)', '2006-10-06 01:15:04.000000', NULL, 1),
(2901888, 403903, 66515, '<td valign="top">I like the choice of "unrelatedness" here. The feather is soft and neutral in color. The guitar has symmetrical lines but also has nice curves that compliment the feather well. Your positioning of the feather works well and the field of view you''ve used really gives a good feeling of depth.</td>', 'I like the choice of "unrelatedness" here. The feather is soft and neutral in color. The guitar has symmetrical lines but also has nice curves that compliment the feather well. Your positioning of the feather works well and the field of view you''ve used really gives a good feeling of depth.', '2006-10-06 02:17:23.000000', NULL, 1),
(2901924, 404646, 34618, '<td valign="top">Cute. Crisp. Nice lighting. On target with the Challenge reqs. Bright and upbeat.</td>', 'Cute. Crisp. Nice lighting. On target with the Challenge reqs. Bright and upbeat.', '2006-10-06 02:48:52.000000', NULL, 1);
